with valid_inventory as (select * from inventory where product_id = 3), last_restock_month_summary as (select date_trunc('MONTH', last_restock) last_restock_month, min(quantity) min_quantity, max(quantity) max_quantity from valid_inventory group by date_trunc('MONTH', last_restock)) select last_restock_month, min_quantity, max_quantity from last_restock_month_summary where max_quantity >= 110 order by 1 asc
